from envfile import parse_env


def test_reads_pairs():
    assert parse_env("A=1\nB=two") == {"A": "1", "B": "two"}


def test_skips_empty_lines():
    assert parse_env("A=1\n\nB=2") == {"A": "1", "B": "2"}


def test_skips_comment_lines():
    assert parse_env("# database\nA=1\n  # indented") == {"A": "1"}


def test_strips_matching_quotes():
    assert parse_env("A=\"x y\"\nB='z'") == {"A": "x y", "B": "z"}


def test_keeps_mismatched_quotes():
    assert parse_env("A=\"x'") == {"A": "\"x'"}


def test_keeps_later_equals_signs():
    assert parse_env('URL="a=b"\nC=d=e') == {"URL": "a=b", "C": "d=e"}

